import React from 'react';
import { StyleSheet, View } from 'react-native';
import Svg, { Circle, Path } from 'react-native-svg';

import { pieSlice } from './fileViewLogic';

/**
 * The download pie: laid over a file's picture while the file is arriving, the way an iPhone
 * shows an app being downloaded. The picture is dimmed, a ring is drawn in the middle, and the
 * ring fills clockwise from the top as the file comes in.
 *
 * It is for downloads only. An upload's progress is written in the status line instead.
 */

export type DownloadPieProps = {
  /** How much has arrived, 0 to 1. */
  fraction: number;
  /** The side of the square it covers. */
  size: number;
  /** The corner of the picture underneath, so the dimming does not spill past it. */
  radius?: number;
  color?: string;
};

export function DownloadPie({ fraction, size, radius = 0, color = '#fff' }: DownloadPieProps) {
  const middle = size / 2;
  // The ring takes a little over half the picture; the pie sits just inside it.
  const ring = Math.max(5, size * 0.29);
  const line = Math.max(1.25, size * 0.035);
  const pie = Math.max(1, ring - line * 1.9);
  const slice = pieSlice(fraction, pie, middle, middle);
  return (
    <View
      style={[styles.cover, { borderRadius: radius }]}
      pointerEvents="none"
      accessibilityRole="progressbar"
      accessibilityLabel="Downloading"
      accessibilityValue={{ min: 0, max: 100, now: Math.round(Math.min(1, Math.max(0, fraction)) * 100) }}
    >
      <Svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
        <Circle cx={middle} cy={middle} r={ring} stroke={color} strokeWidth={line} fill="none" opacity={0.95} />
        {slice ? <Path d={slice} fill={color} opacity={0.95} /> : null}
      </Svg>
    </View>
  );
}

const styles = StyleSheet.create({
  cover: {
    position: 'absolute',
    top: 0,
    right: 0,
    bottom: 0,
    left: 0,
    overflow: 'hidden',
    backgroundColor: 'rgba(0,0,0,0.52)',
    alignItems: 'center',
    justifyContent: 'center',
  },
});
